  "name": "all_pairs_gap_linear_clamped_v2",
  "intuition": "Weights pairs by linear positive gap scaled by instance median absolute deviation, clamped for stability and preserving full all-pairs topology with instance conditioning",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
