    "clamp_min",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "instance_obj_mad"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    instance_obj_mad = feature_cache['instance_obj_mad']\n    eps = 1e-6\n    # all pairs winner < loser mask\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamp_only'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    scale = instance_obj_mad[b_idx].clamp_min(eps)\n    scaled_gap = gap / scale\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 5.0))\n    weight_raw = scaled_gap.clamp_min(0.0)\n    weight = weight_raw.clamp(clamp_lo, clamp_hi)\n    meta = {'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamp_only'}\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta=meta)\n"
}

