{
  "name": "all_pairs_gap_rank_blend_simplified",
  "intuition": "Reweight all pairs using positive objective gaps scaled by instance objective std, combined linearly with instance-level rank difference, ensuring stable instance-conditioned weighting without complex margin scaling.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "clamp_only",
    "weight_family": "gap_rank_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_rank_blend"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "rank",
      "instance_obj_std"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    instance_obj_std = feature_cache['instance_obj_std']\n    eps = 1e-6\n    std_safe = instance_obj_std.clamp_min(eps)\n\n    # mask pairs where objective[i] < objective[j]\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_normalized = gap / std_safe[b_idx]\n    gap_positive = gap_normalized.clamp_min(0.0)\n\n    rank_diff = rank[b_idx, loser_idx] - rank[b_idx, winner_idx]\n    lambda_rank = float(extra.get('lambda_rank', 0.5))\n    raw_weight = gap_positive * (1.0 + lambda_rank * rank_diff)\n\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw_weight.nan_to_num(nan=0.0, posinf=clamp_hi, neginf=0.0).clamp(clamp_lo, clamp_hi)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})"
}
