  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    batch_size, n = objective.shape\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.shape[0]\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'margin_rank_blend'})\n    margin = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]  # positive margins\n    eps = 1e-6\n    instance_mad = feature_cache['instance_obj_mad'][b_idx].clamp_min(eps)\n    margin_scaled = margin / instance_mad\n    rank_w = rank[b_idx, winner_idx]\n    rank_l = rank[b_idx, loser_idx]\n    rank_span = (rank_l - rank_w).clamp_min(0.0)\n    lambda_rank = float(extra.get('lambda_rank', 1.0))\n    raw_weight = margin_scaled.clamp_min(0.0) * (1.0 + lambda_rank * rank_span)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw_weight = torch.nan_to_num(raw_weight, nan=0.0, posinf=0.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw_weight, meta={'builder': 'all_pairs', 'weight_family': 'margin_rank_blend'})\n"
