  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    instance_obj_mad = feature_cache['instance_obj_mad']\n    instance_regret_std = feature_cache['instance_regret_std']\n    eps = 1e-6\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_linear_instance_scaled', 'weight_family': 'gap_linear'})\n    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp_min(0.0)\n    norm_gap = gap / instance_obj_mad[b_idx].clamp_min(eps)\n    regret_inv = 1.0 / instance_regret_std[b_idx].clamp_min(eps)\n    weight_raw = norm_gap * regret_inv\n    weight = weight_raw.clamp(min=0.0, max=10.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_linear_instance_scaled', 'weight_family': 'gap_linear'})"
